(() => {
  // Mobile navigation
  const toggle = document.querySelector('.nav-toggle');
  const nav = document.getElementById('site-nav');
  if (toggle && nav) {
    toggle.addEventListener('click', () => {
      const open = nav.classList.toggle('is-open');
      toggle.setAttribute('aria-expanded', String(open));
    });
    nav.addEventListener('click', (e) => {
      if (e.target.closest('a')) {
        nav.classList.remove('is-open');
        toggle.setAttribute('aria-expanded', 'false');
      }
    });
  }

  // Reveal sections as they scroll into view
  const revealEls = document.querySelectorAll('.reveal');
  if ('IntersectionObserver' in window) {
    const io = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
            io.unobserve(entry.target);
          }
        }
      },
      { threshold: 0.12, rootMargin: '0px 0px -40px 0px' },
    );
    revealEls.forEach((el) => io.observe(el));
  } else {
    revealEls.forEach((el) => el.classList.add('is-visible'));
  }

  // "How a session works" animation: plays on click, replayable
  const demo = document.getElementById('demo');
  const replay = document.getElementById('replay');
  const play = () => {
    if (!demo) return;
    demo.classList.remove('is-playing');
    void demo.offsetWidth; // restart CSS animations
    demo.classList.add('is-playing');
  };
  if (demo) {
    demo.addEventListener('click', () => {
      if (!demo.classList.contains('is-playing')) play();
    });
  }
  if (replay) replay.addEventListener('click', play);

  // Pipeline pulse travels the exact height of the node list
  const pipe = document.getElementById('pipe');
  if (pipe) {
    const setTravel = () => {
      const nodes = pipe.querySelectorAll('.node');
      if (nodes.length < 2) return;
      const first = nodes[0].getBoundingClientRect();
      const last = nodes[nodes.length - 1].getBoundingClientRect();
      pipe.style.setProperty('--travel', `${last.top - first.top}px`);
    };
    setTravel();
    window.addEventListener('resize', setTravel);
  }

  const year = document.getElementById('year');
  if (year) year.textContent = String(new Date().getFullYear());
})();

