/* Scene 1 bubbles and scene 4 toast */
.scene .bubble rect,
.scene .bubble path {
  fill: #fff;
}
.scene .bubble text {
  fill: var(--ink);
}
.scene .bubble,
.scene .toast {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: bottom center;
}
.scene .toast rect {
  fill: #fff;
  stroke: var(--signal);
  stroke-width: 1.5;
}
.scene .toast text {
  fill: var(--ink);
}
.scene .toast .check {
  stroke: var(--ok);
}

/* Play state: a 10s choreographed timeline, looped by main.js */
.is-playing .scene .bubble.b1 { animation: say 2s var(--ease) 0.2s both; }
.is-playing .scene .bubble.b2 { animation: say 1.6s var(--ease) 0.9s both; }
.is-playing .scene .tunnel {
  animation: tunnelOn 0.8s ease 2s forwards, dash 1s linear 2s infinite;
}
.is-playing .scene .shield { animation: pop 0.5s var(--ease) 2.4s both; }
.is-playing .scene .shield-ring { animation: ring 1.6s ease-out 2.7s 2; }
.is-playing .scene .packet { animation: travel 1.4s linear infinite; }
.is-playing .scene .packet.p1 { animation-delay: 3s; }
.is-playing .scene .packet.p2 { animation-delay: 3.4s; }
.is-playing .scene .packet.p3 { animation-delay: 3.8s; }
.is-playing .scene .screen-row.r1 { animation: fadeIn 0.3s ease 4s forwards; }
.is-playing .scene .screen-row.r2 { animation: fadeIn 0.3s ease 4.8s forwards; }
.is-playing .scene .screen-row.r3 { animation: fadeIn 0.3s ease 5.6s forwards; }
.is-playing .scene .r1 .check { animation: draw 0.4s ease 4.3s forwards; }
.is-playing .scene .r2 .check { animation: draw 0.4s ease 5.1s forwards; }
.is-playing .scene .r3 .check { animation: draw 0.4s ease 5.9s forwards; }
.is-playing .scene .done-badge { animation: pop 0.5s var(--ease) 6.6s both; }
.is-playing .scene .clock-hand { animation: spin 2s linear 6.6s infinite; }
.is-playing .scene .toast { animation: pop 0.5s var(--ease) 7.6s both; }
.is-playing .scene .toast .check { animation: draw 0.4s ease 8s forwards; }

/* Pause freezes every running animation in the player */
.demo-frame.is-paused *,
.demo-frame.is-paused *::before,
.demo-frame.is-paused *::after {
  animation-play-state: paused !important;
}

@keyframes say {
  0% {
    opacity: 0;
    transform: translateY(8px) scale(0.9);
  }
  15%,
  80% {
    opacity: 1;
    transform: none;
  }
  100% {
    opacity: 0;
    transform: translateY(-6px);
  }
}
@keyframes tunnelOn {
  to {
    opacity: 1;
  }
}
@keyframes dash {
  to {
    stroke-dashoffset: -12;
  }
}
@keyframes pop {
  0% {
    opacity: 0;
    transform: scale(0.4);
  }
  70% {
    opacity: 1;
    transform: scale(1.12);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}
@keyframes ring {
  0% {
    opacity: 0.9;
    transform: scale(0.8);
  }
  100% {
    opacity: 0;
    transform: scale(2.2);
  }
}
@keyframes travel {
  0% {
    opacity: 0;
    transform: translateX(0);
  }
  10%,
  90% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: translateX(232px);
  }
}
@keyframes draw {
  to {
    stroke-dashoffset: 0;
  }
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.scene-wrap {
  position: relative;
}

/* Subtitle, like captions on a video */
.subtitle {
  position: absolute;
  left: 50%;
  bottom: 8px;
  transform: translateX(-50%);
  margin: 0;
  padding: 6px 14px;
  background: rgba(14, 27, 44, 0.85);
  color: #fff;
  font-size: 0.88rem;
  border-radius: 3px;
  white-space: nowrap;
  opacity: 0;
  transition: opacity 0.3s;
  pointer-events: none;
}
.subtitle.is-on {
  opacity: 1;
}

/* Chapters under the scene, clickable */
.demo-steps {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border-top: 1px solid rgba(143, 216, 236, 0.3);
}
.demo-steps li {
  position: relative;
  border-right: 1px solid rgba(143, 216, 236, 0.18);
}
.demo-steps li:last-child {
  border-right: 0;
}
.demo-steps button {
  display: block;
  width: 100%;
  height: 100%;
  padding: 14px 14px 16px;
  background: none;
  border: 0;
  text-align: left;
  font: 400 0.82rem/1.35 var(--font-body);
  color: rgba(255, 255, 255, 0.5);
  cursor: pointer;
  transition: color 0.3s, background 0.3s;
}
.demo-steps button:hover {
  background: rgba(143, 216, 236, 0.08);
  color: #fff;
}
.demo-steps b {
  display: block;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  color: var(--cyan);
  font-weight: 500;
  margin-bottom: 4px;
}
.demo-steps li::before {
  content: '';
  position: absolute;
  top: -1px;
  left: 0;
  height: 2px;
  width: 100%;
  background: var(--signal);
  transform: scaleX(var(--p, 0));
  transform-origin: left;
}
.demo-steps li.is-active button,
.demo-steps li.is-done button {
  color: #fff;
}

/* Player controls */
.controls {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  border-top: 1px solid rgba(143, 216, 236, 0.3);
  background: rgba(14, 27, 44, 0.35);
}
.ctrl {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  padding: 0;
  border: 1px solid rgba(143, 216, 236, 0.4);
  border-radius: 50%;
  background: transparent;
  color: #fff;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s;
}
.ctrl:hover {
  background: var(--signal);
  border-color: var(--signal);
}
.ctrl svg {
  width: 14px;
  height: 14px;
  fill: currentColor;
}
.ctrl .i-pause {
  display: none;
}
.demo-frame.is-playing:not(.is-paused) .ctrl .i-play {
  display: none;
}
.demo-frame.is-playing:not(.is-paused) .ctrl .i-pause {
  display: block;
}
.track {
  position: relative;
  flex: 1;
  height: 4px;
  background: rgba(143, 216, 236, 0.25);
  border-radius: 2px;
  overflow: hidden;
}
.track-fill {
  position: absolute;
  inset: 0;
  background: var(--signal);
  transform: scaleX(var(--progress, 0));
  transform-origin: left;
}
.controls .time {
  font-size: 0.7rem;
  color: var(--cyan);
  min-width: 82px;
  text-align: right;
}

.play-btn {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: rgba(15, 47, 82, 0.55);
  border: 0;
  color: #fff;
  cursor: pointer;
  transition: opacity 0.35s;
  font: inherit;
}
.play-btn .disc {
  width: 84px;
  height: 84px;
  border-radius: 50%;
  background: var(--signal);
  display: grid;
  place-items: center;
  box-shadow: 0 0 0 0 rgba(255, 90, 31, 0.6);
  animation: beacon 2s infinite;
}
.play-btn .disc svg {
  width: 28px;
  margin-left: 4px;
}
.play-btn .hint {
  margin-top: 14px;
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.play-btn > span {
  display: grid;
  justify-items: center;
}
.demo-frame.is-started .play-btn {
  opacity: 0;
  pointer-events: none;
}
@keyframes beacon {
  70% {
    box-shadow: 0 0 0 22px rgba(255, 90, 31, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(255, 90, 31, 0);
  }
}

.demo-caption {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 22px;
  color: var(--ink-3);
}

@media (max-width: 560px) {
  .demo-steps {
    grid-template-columns: 1fr 1fr;
  }
  .demo-steps li:nth-child(2) {
    border-right: 0;
  }
  .subtitle {
    font-size: 0.75rem;
  }
}

