12	export function createApp(store) {
13	  const app = express();
14	
15	  // Cloud Run sits behind one Google front-end proxy; needed for correct client IPs in rate limiting.
16	  app.set('trust proxy', 1);
17	  app.disable('x-powered-by');
18	
19	  app.use(
20	    helmet({
21	      contentSecurityPolicy: {
22	        directives: {
23	          defaultSrc: ["'self'"],
24	          scriptSrc: ["'self'"],
25	          styleSrc: ["'self'", 'https://fonts.googleapis.com'],
26	          fontSrc: ["'self'", 'https://fonts.gstatic.com'],
27	          imgSrc: ["'self'", 'data:'],
28	          connectSrc: ["'self'"],
29	          formAction: ["'self'"],
30	          frameAncestors: ["'none'"],
31	          objectSrc: ["'none'"],
32	          baseUri: ["'self'"],
33	          upgradeInsecureRequests: [],
34	        },
35	      },
36	      strictTransportSecurity: { maxAge: 63072000, includeSubDomains: true, preload: true },
37	      referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
38	    }),
39	  );
40	  app.use(compression());
41	
42	  app.get('/healthz', (_req, res) => res.status(200).json({ ok: true }));
43	  app.get('/readyz', async (_req, res) => {
44	    try {
45	      await store.ping();
46	      res.status(200).json({ ok: true, storage: store.kind });
47	    } catch (err) {
48	      log.error('Readiness check failed', { error: err.message });
49	      res.status(503).json({ ok: false });
50	    }
51	  });
52	
53	  const bookingLimiter = rateLimit({
54	    windowMs: 15 * 60 * 1000,
55	    limit: 5,
56	    standardHeaders: 'draft-7',
57	    legacyHeaders: false,
58	    message: { ok: false, message: 'Too many requests. Please try again in a few minutes.' },
59	  });
60	
61	  app.post('/api/bookings', bookingLimiter, express.json({ limit: '16kb' }), async (req, res) => {
