  padding: 9px 0;
  border-bottom: 1px dashed var(--line-strong);
  font-size: 0.95rem;
}
.rank li:last-child {
  border-bottom: 0;
}
.rank b {
  font-family: var(--font-mono);
  font-weight: 500;
}
.rank .empty {
  color: var(--ink-3);
}

