.table-wrap {
  overflow-x: auto;
}
table.data {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.88rem;
}
table.data th,
table.data td {
  text-align: left;
  padding: 9px 10px;
  border-bottom: 1px solid var(--line);
  vertical-align: top;
}
table.data th {
  font: 500 0.7rem var(--font-mono);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-3);
}
table.data td.wrap-text {
  min-width: 260px;
  max-width: 420px;
}

.note {
  color: var(--ink-3);
  font-size: 0.85rem;
}

@media (max-width: 860px) {
  .kpis,
  .grid {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 560px) {
  .kpis,
