/* Private stats page. Reuses the site's tokens from /styles.css. */
:root {
  --bar: #2f6aa8; /* single-series chart colour (validated: lightness, chroma, contrast) */
}

.admin {
  padding: 40px 0 80px;
}
.brand {
  font-size: 1.2rem;
}

.range {
  display: flex;
  gap: 6px;
}
.range button {
  padding: 8px 14px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius);
  background: transparent;
  color: var(--ink-2);
  font: 500 0.88rem var(--font-body);
  cursor: pointer;
}
.range button[aria-pressed='true'] {
  background: var(--ink);
  border-color: var(--ink);
  color: var(--paper);
}

.status {
  color: var(--ink-3);
  margin: 0 0 20px;
}
.status.is-error {
  color: var(--error);
}

.kpis {
  padding: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  background: var(--line-strong);
  border: 1px solid var(--line-strong);
  margin-bottom: 28px;
}
.kpi {
  background: var(--paper);
  padding: 20px 22px;
}
.kpi .mono {
  color: var(--ink-3);
}
.kpi strong {
  display: block;
  margin-top: 6px;
  font: 400 2.4rem/1 var(--font-display);
  color: var(--ink);
}

.panel {
  position: relative;
  padding: 24px;
  margin-bottom: 28px;
  background: var(--paper);
  border: 1px solid var(--line-strong);
}
.panel h2 {
  font-size: 1.35rem;
  margin-bottom: 16px;
}

.grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0 28px;
}

/* Bar chart */
.chart svg {
  width: 100%;
  height: 240px;
  overflow: visible;
}
.chart .grid-line {
  stroke: var(--line);
  stroke-width: 1;
}
.chart .axis-label {
  fill: var(--ink-3);
  font: 11px var(--font-mono);
}
.chart .bar {
  fill: var(--bar);
  pointer-events: none; /* the wider .hit rect underneath owns hover */
}
.chart .hit {
  fill: transparent;
  cursor: default;
}
.chart .hit:hover + .bar,
.chart .bar.is-hover {
  fill: var(--ink);
}
.tooltip {
  position: absolute;
  pointer-events: none;
  padding: 8px 10px;
  background: var(--ink);
  color: var(--paper);
  font-size: 0.82rem;
  line-height: 1.4;
  border-radius: 3px;
  white-space: nowrap;
  transform: translate(-50%, -100%);
}

details {
  margin-top: 14px;
}
summary {
  cursor: pointer;
  color: var(--ink-2);
  font-size: 0.9rem;
}

/* Ranked lists */
.rank {
  list-style: none;
  margin: 0;
  padding: 0;
}
.rank li {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px;
  padding: 9px 0;
  border-bottom: 1px dashed var(--line-strong);
  font-size: 0.95rem;
}
.rank li:last-child {
  border-bottom: 0;
}
.rank b {
  font-family: var(--font-mono);
  font-weight: 500;
}
.rank .empty {
  color: var(--ink-3);
}

/* Tables */
.table-wrap {
  overflow-x: auto;
}
table.data {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.88rem;
}
table.data th,
table.data td {
  text-align: left;
  padding: 9px 10px;
  border-bottom: 1px solid var(--line);
  vertical-align: top;
}
table.data th {
  font: 500 0.7rem var(--font-mono);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-3);
}
table.data td.wrap-text {
  min-width: 260px;
  max-width: 420px;
}

.note {
  color: var(--ink-3);
  font-size: 0.85rem;
}

@media (max-width: 860px) {
  .kpis,
  .grid {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 560px) {
  .kpis,
  .grid {
    grid-template-columns: 1fr;
  }
  .site-header .wrap {
    height: auto;
    padding: 12px 0;
    flex-wrap: wrap;
    gap: 10px;
  }
}
